namespace Aspose.Pdf.Text;

/// <summary>
/// Self-contained GBK (codepage 936 / Adobe-GB1, Simplified Chinese) two-byte
/// code -> Unicode table. Lets the renderer decode text from non-embedded
/// predefined GBK-EUC-H CMaps without depending on the
/// System.Text.Encoding.CodePages package. Generated from the standard GBK
/// mapping (identical to Windows codepage 936).
/// </summary>
internal static class GbkTable
{
    private static ushort[]? _table;
    private static ushort[] Table => _table ??= Decode(Data);

    /// <summary>GBK byte-code -> Unicode codepoint, or null when unmapped.</summary>
    public static int? ToUnicode(int code)
    {
        if (code <= 0x7F) return code;            // ASCII single byte
        int lead = code >> 8, trail = code & 0xFF;
        if (lead < 0x81 || lead > 0xFE) return null;
        if (trail < 0x40 || trail > 0xFE || trail == 0x7F) return null;
        int ti = trail < 0x7F ? trail - 0x40 : trail - 0x41;
        var u = Table[(lead - 0x81) * 190 + ti];
        return u == 0 ? (int?)null : u;
    }

    private static ushort[] Decode(string b64)
    {
        var raw = System.Convert.FromBase64String(b64);
        var r = new ushort[raw.Length / 2];
        for (int i = 0; i < r.Length; i++)
            r[i] = (ushort)(raw[i * 2] | (raw[i * 2 + 1] << 8));
        return r;
    }

